-- Phase 7: Customer success and support hub. Additive; run after 011.
BEGIN;
CREATE OR REPLACE FUNCTION public.can_manage_support(p_org UUID) RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.organisation_memberships m WHERE m.organisation_id=p_org AND m.user_id=auth.uid() AND m.is_active AND m.role IN('Organisation Owner','Privacy Admin','Privacy Lead'));
$$;
REVOKE ALL ON FUNCTION public.can_manage_support(UUID) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.can_manage_support(UUID) TO authenticated;
CREATE TABLE IF NOT EXISTS public.support_tickets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organisation_id UUID NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE, ticket_number TEXT NOT NULL UNIQUE DEFAULT ('SUP-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))), requester_user_id UUID NOT NULL REFERENCES auth.users(id), ticket_type TEXT NOT NULL CHECK(ticket_type IN('Bug','Contact Support','Compliance Help','Technical Support','Billing Support','Security Incident','General Feedback')), title TEXT NOT NULL CHECK(length(btrim(title)) BETWEEN 3 AND 200), description TEXT NOT NULL CHECK(length(btrim(description)) BETWEEN 5 AND 8000), category TEXT, priority TEXT NOT NULL DEFAULT 'Medium' CHECK(priority IN('Low','Medium','High','Critical')), status TEXT NOT NULL DEFAULT 'New' CHECK(status IN('New','Open','In Review','Waiting for Customer','Escalated','Resolved','Closed')), assigned_to UUID REFERENCES auth.users(id), browser TEXT, operating_system TEXT, screen_resolution TEXT, app_version TEXT, reproduction_steps TEXT, expected_behaviour TEXT, actual_behaviour TEXT, resolution_notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), resolved_at TIMESTAMPTZ, UNIQUE(organisation_id,id));
CREATE TABLE IF NOT EXISTS public.support_ticket_replies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organisation_id UUID NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE, ticket_id UUID NOT NULL, author_user_id UUID NOT NULL REFERENCES auth.users(id), body TEXT NOT NULL CHECK(length(btrim(body)) BETWEEN 1 AND 8000), is_internal BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT support_reply_ticket_fk FOREIGN KEY(organisation_id,ticket_id) REFERENCES public.support_tickets(organisation_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS public.support_ticket_attachments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organisation_id UUID NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE, ticket_id UUID NOT NULL, file_name TEXT NOT NULL CHECK(length(btrim(file_name)) BETWEEN 1 AND 255), storage_path TEXT NOT NULL CHECK(length(storage_path) BETWEEN 1 AND 600), mime_type TEXT NOT NULL CHECK(mime_type IN('image/png','image/jpeg','application/pdf','text/plain')), size_bytes INTEGER NOT NULL CHECK(size_bytes > 0 AND size_bytes <= 10485760), created_by UUID NOT NULL REFERENCES auth.users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT support_attachment_ticket_fk FOREIGN KEY(organisation_id,ticket_id) REFERENCES public.support_tickets(organisation_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS public.support_ticket_activity (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organisation_id UUID NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE, ticket_id UUID NOT NULL, actor_user_id UUID REFERENCES auth.users(id), action TEXT NOT NULL, metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT support_activity_ticket_fk FOREIGN KEY(organisation_id,ticket_id) REFERENCES public.support_tickets(organisation_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS public.feature_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organisation_id UUID NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE, requester_user_id UUID NOT NULL REFERENCES auth.users(id), title TEXT NOT NULL CHECK(length(btrim(title)) BETWEEN 3 AND 200), business_problem TEXT NOT NULL CHECK(length(btrim(business_problem)) BETWEEN 5 AND 5000), proposed_solution TEXT, expected_benefit TEXT, department TEXT, priority TEXT NOT NULL DEFAULT 'Medium' CHECK(priority IN('Low','Medium','High','Critical')), status TEXT NOT NULL DEFAULT 'Under Review' CHECK(status IN('Under Review','Planned','In Development','Released','Declined')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(organisation_id,id));
CREATE TABLE IF NOT EXISTS public.feature_request_votes (organisation_id UUID NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE, feature_request_id UUID NOT NULL, user_id UUID NOT NULL REFERENCES auth.users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(feature_request_id,user_id), CONSTRAINT feature_vote_fk FOREIGN KEY(organisation_id,feature_request_id) REFERENCES public.feature_requests(organisation_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS public.customer_feedback (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organisation_id UUID NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES auth.users(id), rating SMALLINT NOT NULL CHECK(rating BETWEEN 1 AND 5), satisfaction_score SMALLINT CHECK(satisfaction_score BETWEEN 0 AND 10), comments TEXT, suggestions TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.knowledge_base_articles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title TEXT NOT NULL, summary TEXT NOT NULL, body TEXT NOT NULL, category TEXT NOT NULL CHECK(category IN('FAQ','DPDP Guide','Tutorial','Product Documentation','Troubleshooting','Release Notes')), is_published BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE public.support_tickets ENABLE ROW LEVEL SECURITY; CREATE POLICY "Ticket owner or admin" ON public.support_tickets FOR ALL TO authenticated USING(public.can_manage_support(organisation_id) OR requester_user_id=auth.uid()) WITH CHECK(public.can_manage_support(organisation_id) OR requester_user_id=auth.uid());
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['support_ticket_replies','support_ticket_attachments','support_ticket_activity'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY "Ticket participant or admin %s" ON public.%I FOR ALL TO authenticated USING(public.can_manage_support(organisation_id) OR EXISTS(SELECT 1 FROM public.support_tickets st WHERE st.id=ticket_id AND st.organisation_id=organisation_id AND st.requester_user_id=auth.uid())) WITH CHECK(public.can_manage_support(organisation_id) OR EXISTS(SELECT 1 FROM public.support_tickets st WHERE st.id=ticket_id AND st.organisation_id=organisation_id AND st.requester_user_id=auth.uid()))',t,t); END LOOP; END $$;
ALTER TABLE public.feature_requests ENABLE ROW LEVEL SECURITY; CREATE POLICY "Feature requester or admin" ON public.feature_requests FOR ALL TO authenticated USING(public.can_manage_support(organisation_id) OR requester_user_id=auth.uid()) WITH CHECK(public.can_manage_support(organisation_id) OR requester_user_id=auth.uid());
ALTER TABLE public.feature_request_votes ENABLE ROW LEVEL SECURITY; CREATE POLICY "Feature voters or admin" ON public.feature_request_votes FOR ALL TO authenticated USING(public.can_manage_support(organisation_id) OR user_id=auth.uid()) WITH CHECK(public.can_manage_support(organisation_id) OR user_id=auth.uid());
ALTER TABLE public.customer_feedback ENABLE ROW LEVEL SECURITY; CREATE POLICY "Feedback owner or admin" ON public.customer_feedback FOR ALL TO authenticated USING(public.can_manage_support(organisation_id) OR user_id=auth.uid()) WITH CHECK(public.can_manage_support(organisation_id) OR user_id=auth.uid());
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['support_tickets','support_ticket_replies','support_ticket_attachments','support_ticket_activity','feature_requests','feature_request_votes','customer_feedback'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS audit_%s_changes ON public.%I',t,t); EXECUTE format('CREATE TRIGGER audit_%s_changes AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.audit_privacy_operation()',t,t); END LOOP; END $$;
ALTER TABLE public.knowledge_base_articles ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Authenticated read knowledge base" ON public.knowledge_base_articles; CREATE POLICY "Authenticated read knowledge base" ON public.knowledge_base_articles FOR SELECT TO authenticated USING(is_published);
CREATE INDEX IF NOT EXISTS idx_support_tickets_org_status ON public.support_tickets(organisation_id,status,created_at DESC); CREATE INDEX IF NOT EXISTS idx_support_tickets_requester ON public.support_tickets(organisation_id,requester_user_id,created_at DESC);
COMMIT;
